draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character 1
  ctx.beginPath();
  ctx.arc(W/4 + 20*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + 20*Math.sin(t), H/2 + 20);
  ctx.lineTo(W/4 + 20*Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + 20*Math.sin(t), H/2 + 40);
  ctx.lineTo(W/4 - 20 + 20*Math.sin(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + 20*Math.sin(t), H/2 + 40);
  ctx.lineTo(W/4 + 20 + 20*Math.sin(t), H/2 + 60);
  ctx.stroke();

  // character 2
  ctx.beginPath();
  ctx.arc(W - W/4 + 20*Math.cos(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + 20*Math.cos(t), H/2 + 20);
  ctx.lineTo(W - W/4 + 20*Math.cos(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + 20*Math.cos(t), H/2 + 40);
  ctx.lineTo(W - W/4 - 20 + 20*Math.cos(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 + 20*Math.cos(t), H/2 + 40);
  ctx.lineTo(W - W/4 + 20 + 20*Math.cos(t), H/2 + 60);
  ctx.stroke();

  // bond
  ctx.beginPath();
  ctx.moveTo(W/2 - 20*Math.sin(2*t), H/2);
  ctx.lineTo(W/2 + 20*Math.sin(2*t), H/2);
  ctx.stroke();

  ctx.restore();
}
